fn cursor(sequence: u64) -> FeedCursor {
    if sequence == 0 {
        FeedCursor::beginning()
    } else {
        FeedCursor {
            lineage: LINEAGE,
            sequence,
        }
    }
}

/// Checks one reader against the literal legacy stream and pages.
fn check_legacy(read: &dyn Fn(&FeedCursor, usize) -> ChangeBatch) {
    let expected = legacy_expected();
    let all = read(&FeedCursor::beginning(), 10_000);
    assert_eq!(all.changes, expected);
    assert_eq!(
        (all.next, all.has_more, all.head),
        (cursor(14), false, 14),
        "full read"
    );
    assert_eq!(
        all.next.to_token(),
        "vlc1.0123456789abcdef.000000000000000e.77659153"
    );
    for (from, events, next, has_more, head, token) in ONE_EVENT_PAGES {
        for limit in [0, 1] {
            let page = read(&cursor(from), limit);
            let got: Vec<(u64, u32)> = page
                .changes
                .iter()
                .map(|change| (change.sequence, change.ordinal))
                .collect();
            assert_eq!(got, events, "page after {from}, limit {limit}");
            for change in &page.changes {
                assert!(expected.contains(change), "page after {from}: {change:?}");
            }
            assert_eq!(
                (page.next, page.has_more, page.head),
                (cursor(next), has_more, head),
                "page after {from}, limit {limit}"
            );
            assert_eq!(page.next.to_token(), token);
            assert_eq!(FeedCursor::from_token(token).unwrap(), cursor(next));
        }
    }
}

/// Literal JSON of every graph event of the legacy stream (`graph_json`,
/// the REST/webhook/C ABI shape), in stream order.
#[cfg(feature = "json")]
const LEGACY_GRAPH_JSON: [&str; 10] = [
    r#"{"graph":"g","type":"graph_created"}"#,
    concat!(
        r#"{"graph":"g","operations":["#,
        r#"{"created":true,"id":"0","key":"a","labels":[],"op":"node_upserted","properties":{}},"#,
        r#"{"created":true,"id":"1","key":"b","labels":[],"op":"node_upserted","properties":{}},"#,
        r#"{"created":true,"id":"2","key":"c","labels":[],"op":"node_upserted","properties":{}},"#,
        r#"{"created":true,"destination":"1","destination_key":"b","id":"0","key":"ab","op":"edge_upserted","properties":{},"relationship":"KNOWS","source":"0","source_key":"a"},"#,
        r#"{"created":true,"destination":"1","destination_key":"b","id":"1","key":null,"op":"edge_upserted","properties":{},"relationship":"SELF","source":"1","source_key":"b"},"#,
        r#"{"created":true,"destination":"2","destination_key":"c","id":"2","key":null,"op":"edge_upserted","properties":{},"relationship":"KNOWS","source":"0","source_key":"a"},"#,
        r#"{"collection":"default","node":"0","node_key":"a","op":"attached","record":"1"}"#,
        r#"],"revision":"4","type":"graph_batch"}"#
    ),
    concat!(
        r#"{"graph":"g","operations":["#,
        r#"{"add_labels":["X"],"id":"1","key":"b","op":"node_patched","remove_labels":[],"set":{},"unset":[]}"#,
        r#"],"revision":"6","type":"graph_batch"}"#
    ),
    concat!(
        r#"{"graph":"g","operations":["#,
        r#"{"created":true,"id":"3","key":"a","labels":[],"op":"node_upserted","properties":{}},"#,
        r#"{"collection":"default","node":"3","node_key":"a","op":"attached","record":"1"}"#,
        r#"],"revision":"7","type":"graph_batch"}"#
    ),
    concat!(
        r#"{"graph":"g","operations":["#,
        r#"{"created":true,"destination":"3","destination_key":"a","id":"3","key":"ca","op":"edge_upserted","properties":{},"relationship":"KNOWS","source":"2","source_key":"c"}"#,
        r#"],"revision":"9","type":"graph_batch"}"#
    ),
    concat!(
        r#"{"graph":"g","operations":["#,
        r#"{"created":false,"id":"2","key":"c","labels":["Kept"],"op":"node_upserted","properties":{}}"#,
        r#"],"revision":"10","type":"graph_batch"}"#
    ),
    concat!(
        r#"{"graph":"g","operations":["#,
        r#"{"id":"3","key":"ca","op":"edge_deleted"},"#,
        r#"{"collection":"default","node":"3","node_key":"a","op":"detached","record":"1"},"#,
        r#"{"id":"3","key":"a","op":"node_deleted"}"#,
        r#"],"revision":"11","type":"graph_batch"}"#
    ),
    r#"{"graph":"g","type":"graph_dropped"}"#,
    r#"{"graph":"g","type":"graph_created"}"#,
    concat!(
        r#"{"graph":"g","operations":["#,
        r#"{"created":true,"id":"0","key":"a","labels":[],"op":"node_upserted","properties":{}}"#,
        r#"],"revision":"14","type":"graph_batch"}"#
    ),
];

#[cfg(feature = "json")]
fn check_legacy_json(changes: &[Change]) {
    let json: Vec<String> = changes
        .iter()
        .filter_map(|change| change.kind.graph_json())
        .map(|value| value.to_string())
        .collect();
    assert_eq!(json, LEGACY_GRAPH_JSON);
}

/// Phase-2 commit 1 (captured before any feed change): the exact default-set
/// output, pages and v1 tokens of a hand-built deadline/reclaim log, from an
/// open file, a closed file and an in-memory copy.
#[test]
fn legacy_feed_bytes() {
    let bytes = reclaim_fixture().bytes;
    assert_eq!(
        FeedCursor::beginning().to_token(),
        "vlc1.0000000000000000.0000000000000000.f81d6010"
    );
    assert_eq!(
        cursor(0).to_token(),
        FeedCursor::from_token("vlc1.0000000000000000.0000000000000000.f81d6010")
            .unwrap()
            .to_token()
    );
    let dir = tempdir().unwrap();
    let path = dir.path().join("reclaim.vlite");
    std::fs::write(&path, &bytes).unwrap();

    check_legacy(&|cursor, limit| read_log_changes(&path, None, cursor, limit).unwrap());
    let db = Database::open(&path).unwrap();
    check_legacy(&|cursor, limit| db.changes_after(cursor, limit).unwrap());
    assert_eq!(
        db.feed_cursor().unwrap().to_token(),
        "vlc1.0123456789abcdef.000000000000000e.77659153"
    );
    let memory = Database::open_from_bytes(bytes, None).unwrap();
    check_legacy(&|cursor, limit| memory.changes_after(cursor, limit).unwrap());
    #[cfg(feature = "json")]
    check_legacy_json(
        &db.changes_after(&FeedCursor::beginning(), 10_000)
            .unwrap()
            .changes,
    );
    db.close().unwrap();
}
